layer.css:
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="button"] { color: var(--ryt-bg); background-color: var(--ryt-text); border-radius: 45px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; line-height: 3.75; letter-spacing: 1.5px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 30px; padding-bottom: 0px; padding-left: 30px; transition: background-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out, color 0.2s ease-in-out }
[data-ryt="button"]:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(131, 113, 100); box-shadow: rgb(131, 113, 100) 0px 0px 0px 1px inset; color: rgb(131, 113, 100); background-color: rgb(131, 113, 100) }
